    if (!isRecord(value)) throw new Error(`files[${index}] must be an object.`);
    if (value.kind === 'text-diff') {
        validateScene(value, index, 1);
        return;
    }
    if (value.kind !== 'omitted') {
        throw new Error(`files[${index}].kind must be text-diff or omitted.`);
